#!/usr/bin/env python3
"""Write an atomic NDJSON inventory of Linux symbolic-link resolution depth."""
import base64
import datetime
import errno
import hashlib
import json
import os
import stat
import subprocess
import sys
import tempfile
import time
import uuid
from collections import deque

SCHEMA_VERSION = 1
COLLECTOR = "linux_symlink_depth_v1"
LINUX_SYMLINK_LIMIT = 40
FIND = b"/usr/bin/find"
CONFIG_PATH = "/etc/splunk-symlink-depth.json"
SPOOL_DIR = "/var/lib/splunk-symlink-depth/spool"


def utc(epoch):
    return datetime.datetime.fromtimestamp(epoch, datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def display(value):
    return value.decode(sys.getfilesystemencoding(), errors="backslashreplace")


def encoded(value):
    return base64.b64encode(value).decode("ascii")


def absolute(parts):
    return b"/" + b"/".join(parts)


def classify(error):
    mapping = {errno.ELOOP: "eloop", errno.ENOENT: "unresolved_target", errno.EACCES: "permission_denied", errno.EPERM: "permission_denied", errno.ENOTDIR: "not_directory", errno.ENAMETOOLONG: "name_too_long"}
    return mapping.get(error.errno, "resolution_error"), errno.errorcode.get(error.errno, "UNKNOWN")


def resolve_depth(start):
    pending = deque(start.split(b"/"))
    resolved = []
    followed = attempted = repeated = 0
    seen_links = set()
    candidate = b"/"
    try:
        while pending:
            component = pending.popleft()
            if component in (b"", b"."):
                continue
            if component == b"..":
                if resolved:
                    resolved.pop()
                continue
            candidate = absolute(resolved + [component])
            details = os.lstat(candidate)
            if not stat.S_ISLNK(details.st_mode):
                resolved.append(component)
                if pending and not stat.S_ISDIR(details.st_mode):
                    raise NotADirectoryError(errno.ENOTDIR, "non-directory pathname component", candidate)
                continue
            identity = (details.st_dev, details.st_ino)
            repeated = int(repeated or identity in seen_links)
            seen_links.add(identity)
            attempted = followed + 1
            if followed >= LINUX_SYMLINK_LIMIT:
                return {"chain_depth": followed, "attempted_depth": attempted, "resolution_status": "eloop", "resolution_errno": "ELOOP", "repeated_link_observed": repeated, "terminal": candidate}
            target = os.readlink(candidate)
            followed += 1
            if target.startswith(b"/"):
                resolved = []
            pending = deque(target.split(b"/") + list(pending))
        return {"chain_depth": followed, "attempted_depth": followed, "resolution_status": "ok", "resolution_errno": None, "repeated_link_observed": repeated, "terminal": absolute(resolved)}
    except OSError as error:
        status, error_name = classify(error)
        return {"chain_depth": followed, "attempted_depth": max(attempted, followed), "resolution_status": status, "resolution_errno": error_name, "repeated_link_observed": repeated, "terminal": candidate}


def inside(path, root):
    return root == b"/" or path == root or path.startswith(root.rstrip(b"/") + b"/")


def nul_records(stream):
    pending = b""
    while True:
        block = stream.read(65536)
        if not block:
            break
        pending += block
        fields = pending.split(b"\0")
        pending = fields.pop()
        for field in fields:
            if field:
                yield field
    if pending:
        raise RuntimeError("GNU find output ended without NUL framing")


def configured_roots():
    with open(CONFIG_PATH, "r", encoding="utf-8") as handle:
        values = json.load(handle).get("roots")
    if not isinstance(values, list) or not values:
        raise ValueError("roots must be a non-empty array")
    roots = []
    for value in values:
        if not isinstance(value, str) or not os.path.isabs(value):
            raise ValueError("every root must be an absolute string")
        root = os.fsencode(os.path.realpath(value))
        details = os.stat(root, follow_symlinks=True)
        if not stat.S_ISDIR(details.st_mode):
            raise ValueError("configured root is not a directory")
        for previous, previous_device in roots:
            if details.st_dev == previous_device and os.path.commonpath((previous, root)) in (previous, root):
                raise ValueError("overlapping roots on one device")
        roots.append((root, details.st_dev))
    return roots


def write_event(handle, event):
    handle.write(json.dumps(event, ensure_ascii=True, separators=(",", ":"), sort_keys=True) + "\n")


def main():
    started = int(time.time())
    scan_id = str(uuid.uuid4())
    os.makedirs(SPOOL_DIR, mode=0o750, exist_ok=True)
    descriptor, temporary = tempfile.mkstemp(prefix="." + scan_id + ".", suffix=".tmp", dir=SPOOL_DIR, text=True)
    os.fchmod(descriptor, 0o640)
    final = os.path.join(SPOOL_DIR, scan_id + ".ndjson")
    root_count = completed_roots = failed_roots = symlink_count = 0
    vanished = internal_errors = resolution_issues = max_depth = duplicate_paths = 0
    errors = []
    seen = set()
    output = os.fdopen(descriptor, "w", encoding="utf-8")
    try:
        try:
            roots = configured_roots()
            root_count = len(roots)
            for root, _ in roots:
                scan_error = None
                with tempfile.TemporaryFile() as error_file:
                    process = subprocess.Popen([FIND, b"-P", root, b"-xdev", b"-type", b"l", b"-print0"], stdout=subprocess.PIPE, stderr=error_file)
                    try:
                        for path in nul_records(process.stdout):
                            if path in seen:
                                duplicate_paths += 1
                                continue
                            seen.add(path)
                            try:
                                link = os.lstat(path)
                                if not stat.S_ISLNK(link.st_mode):
                                    vanished += 1
                                    continue
                                target = os.readlink(path)
                                result = resolve_depth(path)
                                terminal = result.pop("terminal")
                                event = {"event_time": utc(started), "schema_version": SCHEMA_VERSION, "record_type": "symlink", "collector": COLLECTOR, "scan_id": scan_id, "scan_started_epoch": started, "scan_root": display(root), "path": display(path), "path_b64": encoded(path), "path_hash": hashlib.sha256(path).hexdigest(), "link_target": display(target), "link_target_b64": encoded(target), "link_device": link.st_dev, "link_inode": link.st_ino, "link_mtime_ns": link.st_mtime_ns, "terminal_path": display(terminal), "terminal_path_b64": encoded(terminal), "target_scope": "inside_scan_root" if inside(terminal, root) else "outside_scan_root"}
                                event.update(result)
                                write_event(output, event)
                                symlink_count += 1
                                max_depth = max(max_depth, result["chain_depth"])
                                resolution_issues += int(result["resolution_status"] != "ok")
                            except FileNotFoundError:
                                vanished += 1
                            except OSError as error:
                                internal_errors += 1
                                errors.append("path collection error: " + type(error).__name__)
                    except Exception as error:
                        scan_error = error
                    finally:
                        if process.stdout:
                            process.stdout.close()
                    exit_code = process.wait()
                    error_file.seek(0)
                    stderr_text = error_file.read(4096).decode("utf-8", errors="replace").strip()
                if scan_error is not None:
                    internal_errors += 1
                    errors.append(type(scan_error).__name__ + ": " + str(scan_error)[:300])
                if exit_code == 0 and scan_error is None:
                    completed_roots += 1
                else:
                    failed_roots += 1
                    errors.append("find failed for " + display(root) + " exit=" + str(exit_code) + " " + stderr_text[:300])
        except Exception as error:
            internal_errors += 1
            errors.append(type(error).__name__ + ": " + str(error)[:500])
        status = "complete" if root_count > 0 and completed_roots == root_count and failed_roots == 0 and internal_errors == 0 else "degraded"
        ended = int(time.time())
        write_event(output, {"event_time": utc(ended), "schema_version": SCHEMA_VERSION, "record_type": "manifest", "collector": COLLECTOR, "collector_status": status, "scan_id": scan_id, "scan_started_epoch": started, "scan_ended_epoch": ended, "scan_duration_seconds": ended - started, "root_count": root_count, "completed_root_count": completed_roots, "failed_root_count": failed_roots, "symlink_count": symlink_count, "resolution_issue_count": resolution_issues, "resolver_internal_error_count": internal_errors, "vanished_path_count": vanished, "duplicate_path_count": duplicate_paths, "max_chain_depth": max_depth, "linux_symlink_limit": LINUX_SYMLINK_LIMIT, "collector_error": " | ".join(errors)[:1000] if errors else None})
        output.flush()
        os.fsync(output.fileno())
    finally:
        output.close()
    os.replace(temporary, final)
    directory = os.open(SPOOL_DIR, os.O_RDONLY | os.O_DIRECTORY)
    try:
        os.fsync(directory)
    finally:
        os.close(directory)
    return 0 if status == "complete" else 1


if __name__ == "__main__":
    raise SystemExit(main())
